N = lambda s: unicodedata.normalize("NFC", s)
def NOTE(t, ar="", en="", tr=""):
    """append a remark to a kit line, before its closing full stop"""
    for k, v in (("ar", ar), ("en", en), ("tr", tr)):
        if v:
            s = t["irab"][k]
            t["irab"][k] = N((s[:-1] if s.endswith(".") else s) + v + ".")
    return t
def TAG(t, *tags):
    for g in tags:
        if g not in t.setdefault("grammar", []): t["grammar"].append(g)
    return t
def HAL_OF(t, owner=("", "", "")):
    """a hal whose owner is NOT the doer: the kit's English line says «the doer's condition», where the Arabic says «صَاحِبِهِ»"""
    t["irab"]["en"] = t["irab"]["en"].replace("it states the doer's condition at the time of the action", "it states the condition of the one it describes at the time of the action")
    return NOTE(t, *owner)
def HIDDEN_AN(t):
    """the kit pastes its Arabic «by» phrase into the English and Turkish lines; say it in each language"""
    t["irab"]["en"] = t["irab"]["en"].replace("put in nasb by أَنْ مُضْمَرَةٍ بَعْدَ حَتَّى", "put in nasb by an أَنْ hidden after حَتَّى")
    t["irab"]["tr"] = t["irab"]["tr"].replace("أَنْ مُضْمَرَةٍ بَعْدَ حَتَّى ile mansûb muzâri", "hattâ'dan sonra gizli «en» ile mansûb muzâri")
    return t
def W(*triples):
    """join note triples into the kit's note_ar / note_en / note_tr"""
    out = ["", "", ""]
    for m in triples:
        out = [a + b for a, b in zip(out, m)]
    return dict(note_ar=out[0], note_en=out[1], note_tr=out[2])
def ISTI(t):
    """a waw / fa that opens a new sentence after a full stop resumes; it does not conjoin"""
    for a, b, k in ((WA_AR, "الْوَاوُ اسْتِئْنَافِيَّةٌ، وَ", "ar"), (FA_AR, "الْفَاءُ اسْتِئْنَافِيَّةٌ، وَ", "ar"),
                    ("The waw conjoins; ", "The waw resumes; ", "en"), ("The fa conjoins; ", "The fa resumes; ", "en"),
                    ("«ve» + ", "Vâv isti'nâf içindir; ", "tr"), ("«bunun üzerine» + ", "Fâ isti'nâf içindir; ", "tr")):
        if t["irab"][k].startswith(a): t["irab"][k] = N(b + t["irab"][k][len(a):])
    return t
